import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;

public class Main {
    static final long mod = 1000000007L;
    static long[][][] dp = new long[55][55][205];
    static long[][] c = new long[55][55];
    static int n, lim, A = 0, B = 0, i, j, k, ii, jj;

    static int min(int a, int b) { return a < b ? a : b; }
    static int max(int a, int b) { return a < b ? b : a; }

    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);
        StringBuilder sb = new StringBuilder();
        n = in.nextInt();
        lim = in.nextInt();
        for (i = 0; i < n; i++) {
            int fk = in.nextInt();
            if (fk == 50) A++;
            else B++;
        }
        dp[A][B][0] = 1;
        c[0][0] = 1;
        for (i = 1; i <= 50; i++) {
            for (j = 0; j <= i; j++) {
                long left = (j - 1 >= 0) ? c[i - 1][j - 1] : 0;
                c[i][j] = left + c[i - 1][j];
            }
        }
        for (k = 1; k <= 4 * n; k++) {
            for (i = A; i >= 0; i--) {
                for (j = B; j >= 0; j--) {
                    int s = k % 2;
                    dp[i][j][k] = 0;
                    if (s != 0) {
                        for (ii = i; ii <= A; ii++) {
                            int f = lim - (ii - i) * 50;
                            if (f >= 0) {
                                f /= 100;
                                f += j;
                                f = min(f, B);
                                for (jj = j; jj <= f; jj++) {
                                    if ((i != ii || j != jj)) {
                                        dp[i][j][k] += (dp[ii][jj][k - 1] * c[ii][ii - i] * c[jj][jj - j]) % mod;
                                        dp[i][j][k] %= mod;
                                    }
                                }
                            }
                        }
                    } else {
                        for (ii = 0; ii <= i; ii++) {
                            int f = lim - (i - ii) * 50;
                            if (f >= 0) {
                                f /= 100;
                                f = max(j - f, 0);
                                for (jj = f; jj <= j; jj++) {
                                    if ((i != ii || j != jj)) {
                                        dp[i][j][k] += (dp[ii][jj][k - 1] * c[A - ii][i - ii] * c[B - jj][j - jj]) % mod;
                                        dp[i][j][k] %= mod;
                                    }
                                }
                            }
                        }
                    }
                    if (dp[0][0][k] != 0) {
                        sb.append(k).append('\n');
                        sb.append(dp[0][0][k]).append('\n');
                        System.out.print(sb);
                        return;
                    }
                }
            }
        }
        sb.append("-1\n0\n");
        System.out.print(sb);
    }

    static class FastReader {
        private final DataInputStream din;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPointer = 0, bytesRead = 0;

        FastReader(InputStream is) { din = new DataInputStream(is); }

        int nextInt() throws IOException {
            int ret = 0;
            int b = read();
            while (b != -1 && b <= ' ') b = read();
            boolean neg = (b == '-');
            if (neg) b = read();
            while (b >= '0' && b <= '9') {
                ret = ret * 10 + (b - '0');
                b = read();
            }
            return neg ? -ret : ret;
        }

        private int read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            if (bytesRead == -1) return -1;
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, 0, buffer.length);
            bufferPointer = 0;
        }
    }
}
